using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class KnownMilitaryTargetTests
{
 static void At(WorldSession s,long time)=>NewGameWorldTests.At(s,time);
 static void Open(WorldSession s){foreach(var m in s.GetActorView(s.PlayerControl).Messages.Where(m=>m.KnownBody==null).ToArray())Assert.Equal(ResultCode.Accepted,s.Open(s.PlayerControl,m.Id,s.Revision).Code);}
 static NewMilitaryInput Input(WorldSession s,NewMilitaryAction action)=>new(new("request:known-target/"+s.Revision+"/"+action),action);
 static void Send(WorldSession s,NewMilitaryAction a,long amount=0){var r=s.DecideNewMilitary(Input(s,a) with{Amount=amount},s.PlayerControl,s.Revision);Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);}
 static WorldSession Ready(){var s=NewGameWorldTests.Session([NewGameWorldTests.Officer(site:"site:kofu",role:StartTemplate.Retainer,lord:"person:shingen")]);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.Request) with{ObservationPolicy=NewGameMilitary.ObservationContract},s.PlayerControl,s.Revision).Code);At(s,2);Open(s);Send(s,NewMilitaryAction.Accept);At(s,4);Open(s);Send(s,NewMilitaryAction.Pickup);Send(s,NewMilitaryAction.Load,100000);Send(s,NewMilitaryAction.Deploy);return s;}
 static WorldSession Away(){var s=Ready();var a=NewGameMilitary.Anchor(s.DiagnosticSnapshot());var r=s.DecideNewMilitary(Input(s,NewMilitaryAction.Form) with{A=new(a.X+90000,a.Y-10000),B=new(a.X+90000,a.Y+10000)},s.PlayerControl,s.Revision);Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);At(s,s.DiagnosticSnapshot().NewMilitary!.Orders.Last().Routes.SelectMany(r=>r).Max(l=>l.EndAt)+1);Send(s,NewMilitaryAction.Handoff);Send(s,NewMilitaryAction.Withdraw);At(s,s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Journeys.Last().Route.Max(l=>l.EndAt)+1);return s;}
 static NewMilitaryInput Move(WorldSession s,KnownMilitaryTarget target)=>Input(s,NewMilitaryAction.PersonalMove) with{A=target.Position,KnownTarget=target};
 [Fact]public void UnknownTargetsAreNotSelectable(){var s=Ready();Assert.Null(NewGameMilitary.SelectKnownTarget(s.DiagnosticSnapshot(),new("unit:never-observed")));Assert.All(NewGameMilitary.KnownMilitary(s.DiagnosticSnapshot()),r=>Assert.StartsWith("observation/",r.Evidence));}
 [Fact]public void KnownMoveDoesNotChaseLaterTrueTroopPosition(){var s=Away();Send(s,NewMilitaryAction.RemoteRecall);var w=s.DiagnosticSnapshot();var target=NewGameMilitary.SelectKnownTarget(w,NewGameMilitary.UnitIds[2])!;var input=Move(s,target);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(input,s.PlayerControl,s.Revision).Code);var journey=s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Journeys.Last();Assert.Equal(target.Position,journey.Route[^1].To);var due=s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Dispatches.Last().DueAt;At(s,due+1);w=s.DiagnosticSnapshot();Assert.NotEqual(target.Position,NewGameMilitary.Position(w,2,s.Seconds));Assert.Equal(target.Position,w.NewMilitary!.Withdrawal!.Journeys.Last().Route[^1].To);Assert.Equal(input,w.NewMilitary.Requests.Single(q=>q.Input.Id==input.Id).Input);Assert.Equal(NewGameMilitary.UnitIds[0],w.ResourceLots.Single(l=>l.Id==NewGameMilitary.Carry).MobileHolder);new WorldSession(w);}
 [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)][InlineData(4)]public void ForgedKnownReferenceIsAtomic(int kind){var s=Away();var target=NewGameMilitary.SelectKnownTarget(s.DiagnosticSnapshot(),NewGameMilitary.UnitIds[2])!;target=kind switch{0=>target with{Position=new(target.Position.X+1,target.Position.Y)},1=>target with{ObservedAt=target.ObservedAt+1},2=>target with{Evidence="observation/999999"},3=>target with{Unit=new("unit:unknown")},_=>target with{Unit=NewGameMilitary.UnitIds[0]}};string before=ContractJson.CanonicalHash(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,s.DecideNewMilitary(Move(s,target),s.PlayerControl,s.Revision).Code);Assert.Equal(before,ContractJson.CanonicalHash(s.DiagnosticSnapshot()));}
 [Fact]public void ForgedSavedReferenceIsRejected(){var s=Away();var input=Move(s,NewGameMilitary.SelectKnownTarget(s.DiagnosticSnapshot(),NewGameMilitary.UnitIds[1])!);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(input,s.PlayerControl,s.Revision).Code);var w=s.DiagnosticSnapshot();int n=Array.FindIndex(w.NewMilitary!.Requests,q=>q.Input.Id==input.Id);var q=w.NewMilitary.Requests[n];w.NewMilitary.Requests[n]=q with{Input=q.Input with{KnownTarget=input.KnownTarget! with{Evidence="letter:unknown"}}};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
 [Fact]public void OldManualMoveStillOmitsReference(){var s=Away();var a=NewGameMilitary.Anchor(s.DiagnosticSnapshot());var input=Input(s,NewMilitaryAction.PersonalMove) with{A=new(a.X-10000,a.Y)};Assert.DoesNotContain("KnownTarget",System.Text.Encoding.UTF8.GetString(ContractJson.Write(input)));Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(input,s.PlayerControl,s.Revision).Code);new WorldSession(s.DiagnosticSnapshot());}
 [Fact]public void SelectedTargetPresentationRoundTripsAndOldNullIsOmitted(){var old=new SavePresentation(0,1);Assert.DoesNotContain("MilitaryTarget",System.Text.Encoding.UTF8.GetString(ContractJson.Write(old)));var selected=old with{MilitaryTarget=NewGameMilitary.UnitIds[2].Value};Assert.Equal(selected,ContractJson.Read<SavePresentation>(ContractJson.Write(selected)));}
 [Fact]public void SelectionIsPartOfTheSameSaveGeneration(){var s=Ready();var w=s.DiagnosticSnapshot();var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"hakutai-known-target",Guid.NewGuid().ToString("N")),w.Definitions);var display=new SavePresentation(0,1,MilitaryTarget:NewGameMilitary.UnitIds[1].Value);store.Save(s,"manual",w.WorldId,display);Assert.Equal(display,store.Prepare("manual").Presentation);}
 [Fact]public void InvalidSelectedTargetPresentationIsRejected(){var s=Ready();var w=s.DiagnosticSnapshot();var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"hakutai-known-target",Guid.NewGuid().ToString("N")),w.Definitions);Assert.Throws<InvalidDataException>(()=>store.Save(s,"manual",w.WorldId,new SavePresentation(0,1,MilitaryTarget:"../")));}
 [Fact]public void OldReferenceDoesNotStandInForLatestObservedEvidence(){var s=Ready();Send(s,NewMilitaryAction.Handoff);Send(s,NewMilitaryAction.Withdraw);var target=NewGameMilitary.SelectKnownTarget(s.DiagnosticSnapshot(),NewGameMilitary.UnitIds[0])!;Send(s,NewMilitaryAction.Observe);Assert.NotEqual(target,NewGameMilitary.SelectKnownTarget(s.DiagnosticSnapshot(),target.Unit));Assert.Equal(ResultCode.NotAvailable,s.DecideNewMilitary(Move(s,target),s.PlayerControl,s.Revision).Code);}
 [Fact]public void ReferenceOnUnrelatedActionIsRejected(){var s=Ready();var target=NewGameMilitary.SelectKnownTarget(s.DiagnosticSnapshot(),NewGameMilitary.UnitIds[0])!;Assert.Equal(ResultCode.NotAvailable,s.DecideNewMilitary(Input(s,NewMilitaryAction.Hold) with{KnownTarget=target},s.PlayerControl,s.Revision).Code);}
 [Fact]public void UnknownReplyCannotBecomeTargetEvidence(){var s=Away();Send(s,NewMilitaryAction.InquireUnitKnown);var d=s.DiagnosticSnapshot().NewMilitary!.UnitInquiry!.Dispatches.Last();At(s,d.DueAt);var w=s.DiagnosticSnapshot();var receipt=w.NewMilitary!.UnitInquiry!.Receipts.Last();var answer=ContractJson.Read<UnitPostInquiryAnswer>(System.Text.Encoding.UTF8.GetBytes(w.Messaging.Messages.Single(m=>m.Id==receipt.ReplyMessage).Body));var target=new KnownMilitaryTarget(NewGameMilitary.UnitIds[0],answer.At,answer.Position,"letter/"+receipt.ReplyMessage);Assert.Equal(ResultCode.NotAvailable,s.DecideNewMilitary(Move(s,target),s.PlayerControl,s.Revision).Code);At(s,receipt.ReplyDueAt);target=NewGameMilitary.SelectKnownTarget(s.DiagnosticSnapshot(),target.Unit)!;Assert.StartsWith("letter/",target.Evidence);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Move(s,target),s.PlayerControl,s.Revision).Code);}
 [Fact]public void KnownMoveRestoresSameFixedDestinationAndFuture(){var s=Away();var target=NewGameMilitary.SelectKnownTarget(s.DiagnosticSnapshot(),NewGameMilitary.UnitIds[1])!;Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Move(s,target),s.PlayerControl,s.Revision).Code);At(s,s.Seconds+3);var w=s.DiagnosticSnapshot();var c=new WorldSession(w);long end=w.NewMilitary!.Withdrawal!.Journeys.Last().Route[^1].EndAt;At(s,end+1);At(c,end+1);Assert.Equal(ContractJson.CanonicalHash(s.DiagnosticSnapshot()),ContractJson.CanonicalHash(c.DiagnosticSnapshot()));Assert.Equal(target.Position,NewGameMilitary.PersonPosition(c.DiagnosticSnapshot(),c.Seconds));}
}
